package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact four API53 controls admitted in Wave57; the historical hard-deleted name
// Derived API53 regression: descriptive metadata is neutralized; Apex assertions are preserved.
func TestRunDeletedTargetAssignmentControls(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeDeleteReference53.cls"), "public without sharing class GladeDeleteReference53 {\n public static List<Object> rows=new List<Object>();\n public static Boolean clearInDelete=false;\n public static Contact selectedView;\n public static void error(String phase,Exception e){rows.add(new Map<String,Object>{'p'=>phase,'type'=>e.getTypeName(),'message'=>e.getMessage()});}\n private static void save(String phase,List<Contact> changes){\n  try{List<Database.SaveResult> results=Database.update(changes,false);List<Object> states=new List<Object>();\n   for(Database.SaveResult result:results){List<Object> errors=new List<Object>();for(Database.Error e:result.getErrors())errors.add(new Map<String,Object>{'code'=>String.valueOf(e.getStatusCode()),'fields'=>e.getFields(),'message'=>e.getMessage()});states.add(new Map<String,Object>{'ok'=>result.isSuccess(),'errors'=>errors});}\n   rows.add(new Map<String,Object>{'p'=>phase,'results'=>states});\n  }catch(Exception e){error(phase,e);}\n }\n public static void state(String phase,Id parentId,Id contactId){\n  try{List<GladeRefParent__c> active=[SELECT Id FROM GladeRefParent__c WHERE Id=:parentId];List<GladeRefParent__c> allRows=[SELECT Id,IsDeleted FROM GladeRefParent__c WHERE Id=:parentId ALL ROWS];Contact c=[SELECT GladeRefParent__c,Description FROM Contact WHERE Id=:contactId];\n   rows.add(new Map<String,Object>{'p'=>phase,'active'=>active.size(),'all'=>allRows.size(),'deleted'=>allRows.size()==1?allRows[0].IsDeleted:null,'refNull'=>c.GladeRefParent__c==null,'refMatch'=>c.GladeRefParent__c==parentId,'description'=>c.Description});\n  }catch(Exception e){error(phase,e);}\n }\n public static void afterInsert(List<GladeRefParent__c> parents){\n  for(GladeRefParent__c parent:parents){\n   state('insert-entry',parent.Id,parent.TargetContact__c);\n   save('assign',new List<Contact>{new Contact(Id=parent.TargetContact__c,GladeRefParent__c=parent.Id)});\n   selectedView=[SELECT Id,GladeRefParent__c,Description FROM Contact WHERE Id=:parent.TargetContact__c];\n   state('assigned',parent.Id,parent.TargetContact__c);\n   if(String.isBlank(parent.Street__c)){\n    try{delete new GladeRefParent__c(Id=parent.Id);rows.add(new Map<String,Object>{'p'=>'delete-return','returned'=>true});}catch(Exception e){error('delete-return',e);}\n    state('deleted',parent.Id,parent.TargetContact__c);\n   }\n  }\n }\n public static void afterDelete(List<GladeRefParent__c> parents){\n  for(GladeRefParent__c parent:parents){state('delete-entry',parent.Id,parent.TargetContact__c);\n   if(clearInDelete){save('clear',new List<Contact>{new Contact(Id=parent.TargetContact__c,GladeRefParent__c=null)});state('cleared',parent.Id,parent.TargetContact__c);}\n  }\n }\n public static void run(Id contactId,Boolean explicitClear,Boolean staleWrite){\n  clearInDelete=explicitClear;Contact before=[SELECT AccountId FROM Contact WHERE Id=:contactId];\n  GladeRefParent__c parent=new GladeRefParent__c(TargetContact__c=contactId,Household_Account__c=before.AccountId);\n  try{insert parent;rows.add(new Map<String,Object>{'p'=>'insert-return','idAssigned'=>parent.Id!=null});}catch(Exception e){error('insert-return',e);}\n  state('controller-entry',parent.Id,contactId);\n  rows.add(new Map<String,Object>{'p'=>'selected-view','available'=>selectedView!=null,'refMatch'=>selectedView!=null&&selectedView.GladeRefParent__c==parent.Id});\n  if(staleWrite&&selectedView!=null){selectedView.Description='owned-after';save('stale-write',new List<Contact>{selectedView});}\n  else save('sparse-write',new List<Contact>{new Contact(Id=contactId,Description='owned-after')});\n  state('controller-after',parent.Id,contactId);\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeDeleteReference53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeDeletedTargetControls53.cls"), "@IsTest private class GladeDeletedTargetControls53 {\n private static void capture(String phase,Database.SaveResult result){List<Object> errors=new List<Object>();for(Database.Error e:result.getErrors())errors.add(new Map<String,Object>{'code'=>String.valueOf(e.getStatusCode()),'fields'=>e.getFields(),'message'=>e.getMessage()});GladeDeleteReference53.rows.add(new Map<String,Object>{'p'=>phase,'ok'=>result.isSuccess(),'idAssigned'=>result.getId()!=null,'errors'=>errors});}\n private static void run(String mode){\n  Account household=new Account(Name='owned-household');insert household;Contact c=new Contact(LastName='owned-before',AccountId=household.Id);insert c;\n  Test.startTest();GladeDeleteReference53.run(c.Id,false,false);\n  Id parentId=GladeDeleteReference53.selectedView.GladeRefParent__c;\n  // Prior lifecycle rows are retained in the unchanged helper, but each new observation emits only the new boundary.\n  GladeDeleteReference53.rows=new List<Object>();\n  GladeDeleteReference53.state('control-before',parentId,c.Id);\n  if(mode=='hard-deleted'){\n   try{List<Database.EmptyRecycleBinResult> emptied=Database.emptyRecycleBin(new List<GladeRefParent__c>{new GladeRefParent__c(Id=parentId)});List<Object> statuses=new List<Object>();for(Database.EmptyRecycleBinResult result:emptied){List<Object> errors=new List<Object>();for(Database.Error e:result.getErrors())errors.add(new Map<String,Object>{'code'=>String.valueOf(e.getStatusCode()),'message'=>e.getMessage()});statuses.add(new Map<String,Object>{'ok'=>result.isSuccess(),'errors'=>errors});}GladeDeleteReference53.rows.add(new Map<String,Object>{'p'=>'empty-recycle-bin','results'=>statuses});}\n   catch(Exception e){GladeDeleteReference53.error('empty-recycle-bin',e);}\n   GladeDeleteReference53.state('after-empty',parentId,c.Id);\n  }\n  Id targetContact=c.Id;\n  try{\n   if(mode=='fresh-child-insert'){\n    Contact fresh=new Contact(LastName='owned-new',AccountId=household.Id,GladeRefParent__c=parentId);Database.SaveResult inserted=Database.insert(fresh,false);capture('fresh-insert',inserted);if(inserted.isSuccess())targetContact=inserted.getId();\n   }else{\n    if(mode=='different-child'){Contact other=new Contact(LastName='owned-other',AccountId=household.Id);insert other;targetContact=other.Id;}\n    Contact changed=new Contact(Id=targetContact,GladeRefParent__c=parentId,Description='owned-explicit');capture('explicit-update',Database.update(changed,false));\n   }\n  }catch(Exception e){GladeDeleteReference53.error('assignment',e);}\n  GladeDeleteReference53.state('control-after',parentId,targetContact);Test.stopTest();\n  String text=JSON.serialize(GladeDeleteReference53.rows);System.assert(text.length()<2900,'Deleted target observation exceeds bound');verify(mode,text);\n }\n @IsTest static void freshAssignmentSameChild(){run('same-child');}\n @IsTest static void freshAssignmentDifferentChild(){run('different-child');}\n @IsTest static void freshChildInsert(){run('fresh-child-insert');}\n @IsTest static void freshAssignmentHardDeleted(){run('hard-deleted');}\n private static void verify(String mode,String text){\n  Map<String,Object> expectedByMode=(Map<String,Object>)JSON.deserializeUntyped('{\"same-child\":[{\"p\":\"control-before\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"explicit-update\",\"errors\":[{\"message\":\"entity is deleted\",\"fields\":[],\"code\":\"ENTITY_IS_DELETED\"}],\"idAssigned\":true,\"ok\":false},{\"p\":\"control-after\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0}],\"different-child\":[{\"p\":\"control-before\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"explicit-update\",\"errors\":[{\"message\":\"entity is deleted\",\"fields\":[],\"code\":\"ENTITY_IS_DELETED\"}],\"idAssigned\":true,\"ok\":false},{\"p\":\"control-after\",\"description\":null,\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0}],\"fresh-child-insert\":[{\"p\":\"control-before\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"fresh-insert\",\"errors\":[{\"message\":\"entity is deleted\",\"fields\":[],\"code\":\"ENTITY_IS_DELETED\"}],\"idAssigned\":false,\"ok\":false},{\"p\":\"control-after\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0}],\"hard-deleted\":[{\"p\":\"control-before\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"empty-recycle-bin\",\"message\":\"Attempt to de-reference a null object\",\"type\":\"System.NullPointerException\"},{\"p\":\"after-empty\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0},{\"p\":\"explicit-update\",\"errors\":[{\"message\":\"entity is deleted\",\"fields\":[],\"code\":\"ENTITY_IS_DELETED\"}],\"idAssigned\":true,\"ok\":false},{\"p\":\"control-after\",\"description\":\"owned-after\",\"refMatch\":false,\"refNull\":true,\"deleted\":true,\"all\":1,\"active\":0}]}');\n  System.assert(expectedByMode.containsKey(mode),'Bound expected case missing');\n  compare(expectedByMode.get(mode),JSON.deserializeUntyped(text),'rows');\n }\n private static void compare(Object expected,Object actual,String path){\n  if(expected instanceof Map<String,Object>){Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;System.assertEquals(want.keySet(),got.keySet(),path+' keys');for(String key:want.keySet())compare(want.get(key),got.get(key),path+'.'+key);}\n  else if(expected instanceof List<Object>){List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;System.assertEquals(want.size(),got.size(),path+' size');for(Integer i=0;i<want.size();i++)compare(want[i],got[i],path+'['+i+']');}\n  else System.assertEquals(expected,actual,path);\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeDeletedTargetControls53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeDeleteReferenceTrigger53.trigger"), "trigger GladeDeleteReferenceTrigger53 on GladeRefParent__c(after insert,after delete){if(Trigger.isInsert)GladeDeleteReference53.afterInsert(Trigger.new);else GladeDeleteReference53.afterDelete(Trigger.old);}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeDeleteReferenceTrigger53.trigger-meta.xml"), "<ApexTrigger xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexTrigger>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeRefParent__c/GladeRefParent__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><label>Owned Reference Parent</label><nameField><displayFormat>R-{000000}</displayFormat><label>Name</label><type>AutoNumber</type></nameField><pluralLabel>Owned Reference Parents</pluralLabel><sharingModel>ControlledByParent</sharingModel></CustomObject>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeRefParent__c/fields/TargetContact__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>TargetContact__c</fullName><deleteConstraint>SetNull</deleteConstraint><label>Target Contact</label><referenceTo>Contact</referenceTo><relationshipLabel>Owned Reference Parents</relationshipLabel><relationshipName>GladeReferenceParents</relationshipName><required>false</required><type>Lookup</type></CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeRefParent__c/fields/Household_Account__c.field-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <fullName>Household_Account__c</fullName>\n    <description>Lookup to the Account associated with this Address.</description>\n    <externalId>false</externalId>\n    <inlineHelpText>Lookup to the Account associated with this Address.</inlineHelpText>\n    <label>Account</label>\n    <referenceTo>Account</referenceTo>\n    <relationshipLabel>Owned Reference Parents</relationshipLabel>\n    <relationshipName>GladeReferenceHousehold</relationshipName>\n    <relationshipOrder>0</relationshipOrder>\n    <reparentableMasterDetail>true</reparentableMasterDetail>\n    <trackFeedHistory>false</trackFeedHistory>\n    <trackTrending>false</trackTrending>\n    <type>MasterDetail</type>\n    <writeRequiresMasterRead>true</writeRequiresMasterRead>\n</CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/Contact/fields/GladeRefParent__c.field-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <fullName>GladeRefParent__c</fullName>\n    <deleteConstraint>SetNull</deleteConstraint>\n    <description>Lookup to the current Address record for this Contact. The application populates the Contact&apos;s Mailing Address field with the street, city, state, and postal code from the current Address record.</description>\n    <externalId>false</externalId>\n    <inlineHelpText>Lookup to the current Address record for this Contact. The application populates the Contact&apos;s Mailing Address field with the street, city, state, and postal code from the current Address record.</inlineHelpText>\n    <label>Current Address</label>\n    <lookupFilter>\n        <active>true</active>\n        <filterItems>\n            <field>GladeRefParent__c.Household_Account__c</field>\n            <operation>equals</operation>\n            <valueField>$Source.AccountId</valueField>\n        </filterItems>\n        <infoMessage>To see all addresses for the Contact&apos;s household, enter A-* in the search window</infoMessage>\n        <isOptional>true</isOptional>\n    </lookupFilter>\n    <referenceTo>GladeRefParent__c</referenceTo>\n    <relationshipLabel>Contacts (Current Address)</relationshipLabel>\n    <relationshipName>GladeContacts</relationshipName>\n    <required>false</required>\n    <trackFeedHistory>false</trackFeedHistory>\n    <type>Lookup</type>\n</CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeRefParent__c/fields/Street__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>Street__c</fullName><label>Street</label><length>255</length><type>Text</type></CustomField>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 4 || got.Passed != 4 || got.Errors != 0 || got.Failed != 0 {
		body, _ := json.Marshal(run)
		t.Fatalf("exact deleted target controls: %s", body)
	}
}
